// ── Workflow runs ────────────────────────────────────────────────────────

export type WorkflowRunStatus = 'queued' | 'running' | 'completed' | 'failed';

// Only the workflows that record a run row. `answer-question` and `ingest-document-version` run
// without one, so they never appear here. Absent on rows written before the field existed.
// `'rescan-conflicts'` is no longer a workflow this codebase starts; kept for existing rows that
// carry it, since no current code path writes it.
export type WorkflowRunType = 'resolve-conflict' | 'sync-source' | 'rescan-conflicts';

export interface WorkflowRun {
  id: string;
  workflowId: string;
  workflowType?: WorkflowRunType;
  status: WorkflowRunStatus;
  errorMessage?: string;
  /**
   * What the run acted on, written at creation. A resolve-conflict run records the conflict it is
   * resolving; a sync-source run records no subject and reads back empty. Both fields are written
   * together or not at all, so render a link only when both are present.
   */
  subjectId?: string;
  subjectType?: string;
  createdAt: string;
}

export function getWorkflowRunById(id: string): Promise<WorkflowRun> {
  return request<WorkflowRun>(`/workflow-runs/${id}`);
}

/**
 * `status` filters the stored row, not live engine state — the list endpoint never queries the
 * workflow engine, unlike the detail route and the event stream. A UI must not present this filter
 * as live.
 */
export type WorkflowRunSortField = 'createdAt' | 'status' | 'workflowType';

export function listWorkflowRuns(params?: {
  workflowId?: string;
  status?: WorkflowRunStatus;
  workflowType?: WorkflowRunType;
  skip?: number;
  limit?: number;
  sort?: WorkflowRunSortField;
  sortDir?: SortDirection;
}): Promise<WithCount<WorkflowRun>> {
  const query = new URLSearchParams();
  if (params?.workflowId) query.set('workflowId', params.workflowId);
  if (params?.status) query.set('status', params.status);
  if (params?.workflowType) query.set('workflowType', params.workflowType);
  if (params?.skip !== undefined) query.set('skip', String(params.skip));
  if (params?.limit !== undefined) query.set('limit', String(params.limit));
  if (params?.sort !== undefined) query.set('sort', params.sort);
  if (params?.sortDir !== undefined) query.set('sortDir', params.sortDir);
  const qs = query.toString();
  return request<WithCount<WorkflowRun>>(`/workflow-runs${qs ? `?${qs}` : ''}`);
}

// A plain URL builder, not a `request<T>()` call — a browser-native EventSource consumes this
// href directly, so there is no JSON body for `request<T>()` to parse.
export function workflowRunEventsUrl(id: string): string {
  return `${API}/workflow-runs/${id}/events`;
}

